s="card"><table><thead><tr><th>Order</th><th>Module Action</th><th>Kind</th><th>Behavior</th><th>Parent</th><th>User Actions</th><th>Module</th></tr></thead><tbody id="rows"></tbody></table></div></div><script src="../engine/config.js?v=0.15.46"></script><script src="../engine/loom-brand.js?v=0.15.46"></script><script src="../engine/registry-client.js?v=0.15.21"></script><script>(()=>{const p=(new URLSearchParams(location.search).get('project')||'').replace(/[^a-z0-9_-]/g,'');if(!p){document.getElementById('title').textContent='Action Registry · no project selected';document.getElementById('peg').href='../home/';document.getElementById('rows').innerHTML='<tr><td colspan="7">Open a project from LOOM Home to inspect its Action Registry.</td></tr>';return;}const c=new PegboardRegistryClient({project:p,apiBase:'../api',fallbackUrl:`../projects/${p}/registry.fallback.json`});document.getElementById('title').textContent=`${p.replace(/-/g,' ')} · Action Registry`;document.getElementById('peg').href=`../pegboard/?project=${p}`;const esc=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[x]));async function render(){const d=await c.load();document.getElementById('rows').innerHTML=(d.modules||[]).map(m=>{const uas=m.user_actions||[];return `<tr><td><code><strong>${esc(m.order_display||m.module.order||'50000')}</strong></code>${m.order_locked?'<br><span class="pill">LOCKED</span>':''}</td><td><strong>${esc(m.action.name)}</strong><br><code>${esc(m.action.id)}</code><br><span class="muted">${esc(m.action.description||'')}</span></td><td><span class="pill">${esc(m.action.kind)}</span></td><td>${esc(m.action.behavior)}</td><td><code>${esc(m.action.parent||'—')}</code></td><td>${uas.length?`<div class="ua">${uas.map(a=>`<span class="pill user" title="${esc(a.description||'')}">${esc(a.name)}<br><code>${esc(a.id)}</code></span>`).join('')}</div>`:'<span class="empty">No user actions declared</span>'}</td><td><code>${esc(m.folder||'